17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String telephone = toE164(owner.getTelephone());
106	        if (telephone == null) {
107	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
108	        }
109	        if (owner.getEmail() != null) {
110	            String email = normalizeEmail(owner.getEmail());
111	            if (email == null) {
112	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	            }
114	            owner.setEmail(email);
115	        }
116	        for (Owner existing : this.clinicService.findAllOwners()) {
117	            if (telephone.equals(toE164(existing.getTelephone()))) {
118	                return new ResponseEntity<>(HttpStatus.CONFLICT);
119	            }
120	        }
121	        owner.setTelephone(telephone);
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(LocalDate.now());
124	        }
125	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
136	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
137	        if (currentOwner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        currentOwner.setAddress(ownerFieldsDto.getAddress());
141	        currentOwner.setCity(ownerFieldsDto.getCity());
142	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
143	        currentOwner.setLastName(ownerFieldsDto.getLastName());
144	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
145	        this.clinicService.saveOwner(currentOwner);
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Transactional
151	    @Override
152	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        this.clinicService.deleteOwner(owner);
158	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        HttpHeaders headers = new HttpHeaders();
169	        Pet pet = petMapper.toPet(petFieldsDto);
170	        owner.setId(ownerId);
171	        pet.setOwner(owner);
172	        pet.getType().setName(null);
173	        this.clinicService.savePet(pet);
174	        PetDto petDto = petMapper.toPetDto(pet);
175	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
176	            .buildAndExpand(pet.getId()).toUri());
177	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
183	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
184	        if (currentOwner != null) {
185	            Pet currentPet = this.clinicService.findPetById(petId);
186	            if (currentPet != null) {
187	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
188	                currentPet.setName(petFieldsDto.getName());
189	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
190	                this.clinicService.savePet(currentPet);
191	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
192	            }
193	        }
194	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
200	        HttpHeaders headers = new HttpHeaders();
201	        Visit visit = visitMapper.toVisit(visitFieldsDto);
202	        Pet pet = new Pet();
203	        pet.setId(petId);
204	        visit.setPet(pet);
205	        this.clinicService.saveVisit(visit);
206	        VisitDto visitDto = visitMapper.toVisitDto(visit);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
208	            .buildAndExpand(visit.getId()).toUri());
209	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
210	    }
211	
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner != null) {
218	            Pet pet = owner.getPet(petId);
219	            if (pet != null) {
220	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
221	            }
222	        }
223	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	    }
225	
226	    /**
227	     * Builds the customer code for a newly created owner, formatted
228	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
229	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
230	     * sequence equal to one more than the current number of owners.
231	     *
232	     * @param lastName the owner's last name
233	     * @return the assigned customer code (e.g. {@code 'SMI-0007'})
234	     */
235	    private String nextCustomerCode(String lastName) {
236	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
237	        int sequence = this.clinicService.findAllOwners().size() + 1;
238	        return String.format("%s-%04d", last3, sequence);
239	    }
240	
241	    /**
242	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
243	     * and brackets are stripped. When the number already carries a leading {@code '+'}
244	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
245	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
246	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
247	     *
248	     * @param telephone the raw telephone value supplied by the client
249	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
250	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
251	     */
252	    private static String toE164(String telephone) {
253	        if (telephone == null) {
254	            return null;
255	        }
256	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
257	        String digits;
258	        if (cleaned.startsWith("+")) {
259	            digits = cleaned.substring(1);
260	        } else {
261	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
262	            digits = "61" + national;
263	        }
264	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
265	    }
266	
267	    /**
268	     * Normalizes an owner email for creation. A present email must be a syntactically
269	     * valid address; the returned value is lower-cased.
270	     *
271	     * @param email the raw email value supplied by the client (never {@code null} here)
272	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
273	     *         address (signalling a 400 Bad Request)
274	     */
275	    private static String normalizeEmail(String email) {
276	        String trimmed = email.trim();
277	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
278	            return null;
279	        }
280	        return trimmed.toLowerCase();
281	    }
282	}
